#include "bell_modal_profile.hpp"

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <stdexcept>

namespace BellOptimizer::Acoustics {
namespace {
constexpr char kMagic[8] = {'B','E','L','L','B','M','P','1'};
constexpr std::uint32_t kVersion = 1;
constexpr std::uint64_t kMaxPayload = 512ULL * 1024ULL * 1024ULL;
constexpr std::uint32_t kMaxVector = 10000000U;
void u32(std::vector<std::uint8_t>& b,std::uint32_t v){for(int i=0;i<4;++i)b.push_back(static_cast<std::uint8_t>(v>>(8*i)));}
void u64(std::vector<std::uint8_t>& b,std::uint64_t v){for(int i=0;i<8;++i)b.push_back(static_cast<std::uint8_t>(v>>(8*i)));}
void real(std::vector<std::uint8_t>& b,double x){std::uint64_t v;std::memcpy(&v,&x,8);u64(b,v);}
void str(std::vector<std::uint8_t>& b,const std::string& s){if(s.empty()||s.size()>1048576)throw std::invalid_argument("invalid modal profile identity string");u32(b,static_cast<std::uint32_t>(s.size()));b.insert(b.end(),s.begin(),s.end());}
void ints(std::vector<std::uint8_t>& b,const std::vector<int>& v){if(v.size()>kMaxVector)throw std::invalid_argument("modal profile vector too large");u32(b,static_cast<std::uint32_t>(v.size()));for(int x:v)u32(b,static_cast<std::uint32_t>(static_cast<std::int32_t>(x)));}
void doubles(std::vector<std::uint8_t>& b,const std::vector<double>& v){if(v.size()>kMaxVector)throw std::invalid_argument("modal profile vector too large");u32(b,static_cast<std::uint32_t>(v.size()));for(double x:v)real(b,x);}
std::uint64_t hash(const std::vector<std::uint8_t>& b){std::uint64_t h=14695981039346656037ULL;for(auto x:b){h^=x;h*=1099511628211ULL;}return h;}
struct Reader{const std::vector<std::uint8_t>& b;std::size_t p=0;void need(std::size_t n){if(n>b.size()-p)throw std::runtime_error("truncated bell modal profile");}std::uint32_t get32(){need(4);std::uint32_t x=0;for(int i=0;i<4;++i)x|=std::uint32_t(b[p++])<<(8*i);return x;}std::uint64_t get64(){need(8);std::uint64_t x=0;for(int i=0;i<8;++i)x|=std::uint64_t(b[p++])<<(8*i);return x;}double getReal(){auto x=get64();double d;std::memcpy(&d,&x,8);if(!std::isfinite(d))throw std::runtime_error("non-finite modal profile value");return d;}std::string getString(){auto n=get32();if(!n||n>1048576)throw std::runtime_error("invalid modal profile identity");need(n);std::string s(b.begin()+p,b.begin()+p+n);p+=n;return s;}std::vector<int> getInts(){auto n=get32();if(n>kMaxVector)throw std::runtime_error("modal profile vector limit");std::vector<int> v;v.reserve(n);for(std::uint32_t i=0;i<n;++i)v.push_back(static_cast<int>(static_cast<std::int32_t>(get32())));return v;}std::vector<double> getDoubles(){auto n=get32();if(n>kMaxVector)throw std::runtime_error("modal profile vector limit");std::vector<double> v;v.reserve(n);for(std::uint32_t i=0;i<n;++i)v.push_back(getReal());return v;}};
void writeProfile(std::vector<std::uint8_t>& b,const BellModalProfile& p){u32(b,kVersion);str(b,p.identity.geometry_fingerprint);str(b,p.identity.material_fingerprint);str(b,p.identity.solver_fingerprint);auto points=[&](const std::vector<Point2D>& v){u32(b,static_cast<std::uint32_t>(v.size()));for(auto q:v){real(b,q.r);real(b,q.z);}};points(p.inner_profile);points(p.outer_profile);u32(b,static_cast<std::uint32_t>(p.modes.size()));for(const auto& m:p.modes){u32(b,static_cast<std::uint32_t>(m.mode_number));real(b,m.eigenvalue);real(b,m.frequency_hz);real(b,m.modal_mass);real(b,m.decay_time);ints(b,m.inner_harmonics);doubles(b,m.inner_radial);doubles(b,m.inner_azimuthal);doubles(b,m.inner_axial);ints(b,m.outer_harmonics);doubles(b,m.outer_radial);doubles(b,m.outer_azimuthal);doubles(b,m.outer_axial);}}
}

bool BellModalProfile::valid() const {
 if(identity.geometry_fingerprint.empty()||identity.material_fingerprint.empty()||identity.solver_fingerprint.empty()||inner_profile.size()<2||outer_profile.size()<2||modes.empty())return false;
 auto validProfile=[](const std::vector<Point2D>& points){for(const auto& p:points)if(!std::isfinite(p.r)||!std::isfinite(p.z)||p.r<0.0)return false;return true;};
 if(!validProfile(inner_profile)||!validProfile(outer_profile))return false;
 for(const auto& m:modes){if(!(m.frequency_hz>0&&std::isfinite(m.frequency_hz))||!std::isfinite(m.eigenvalue)||m.modal_mass<0||!std::isfinite(m.modal_mass)||!std::isfinite(m.decay_time)||m.inner_harmonics.empty()||m.outer_harmonics.empty())return false;const auto ib=m.inner_harmonics.size(),ob=m.outer_harmonics.size();if(m.inner_radial.size()!=inner_profile.size()*ib||m.inner_axial.size()!=inner_profile.size()*ib||(!m.inner_azimuthal.empty()&&m.inner_azimuthal.size()!=inner_profile.size()*ib)||m.outer_radial.size()!=outer_profile.size()*ob||m.outer_axial.size()!=outer_profile.size()*ob||(!m.outer_azimuthal.empty()&&m.outer_azimuthal.size()!=outer_profile.size()*ob))return false;auto finite=[](const std::vector<double>& v){return std::all_of(v.begin(),v.end(),[](double x){return std::isfinite(x);});};if(!finite(m.inner_radial)||!finite(m.inner_azimuthal)||!finite(m.inner_axial)||!finite(m.outer_radial)||!finite(m.outer_azimuthal)||!finite(m.outer_axial))return false;}
 return true;
}

BellModalProfile buildBellModalProfile(const ModalData& data,const std::vector<Point2D>& inner,const std::vector<Point2D>& outer,const AcousticFieldCacheIdentity& id){BellModalProfile p;p.identity=id;p.inner_profile=inner;p.outer_profile=outer;p.modes.reserve(data.modes.size());for(const auto& src:data.modes){CachedStructuralMode m;m.mode_number=src.mode_number;m.eigenvalue=src.eigenvalue;m.frequency_hz=src.frequency_hz;m.modal_mass=src.modal_mass;m.decay_time=src.decay_time;m.inner_harmonics=src.inner_surface_harmonics;m.inner_radial=src.inner_surface_fourier_radial;m.inner_azimuthal=src.inner_surface_fourier_azimuthal;m.inner_axial=src.inner_surface_fourier_axial;m.outer_harmonics=src.outer_surface_harmonics;m.outer_radial=src.outer_surface_fourier_radial;m.outer_azimuthal=src.outer_surface_fourier_azimuthal;m.outer_axial=src.outer_surface_fourier_axial;if(m.inner_harmonics.empty()&&!src.inner_surface_radial.empty()){m.inner_harmonics={0};m.inner_radial=src.inner_surface_radial;m.inner_axial=src.inner_surface_axial;}if(m.outer_harmonics.empty()&&!src.outer_surface_radial.empty()){m.outer_harmonics={0};m.outer_radial=src.outer_surface_radial;m.outer_axial=src.outer_surface_axial;}p.modes.push_back(std::move(m));}if(!p.valid())throw std::invalid_argument("modal data does not contain complete inner/outer boundary traces");return p;}

void saveBellModalProfile(const std::string& path,const BellModalProfile& p){if(path.empty()||!p.valid())throw std::invalid_argument("invalid bell modal profile or path");std::vector<std::uint8_t> payload;writeProfile(payload,p);if(payload.size()>kMaxPayload)throw std::runtime_error("bell modal profile exceeds size limit");std::ofstream out(path,std::ios::binary|std::ios::trunc);if(!out)throw std::runtime_error("cannot open bell modal profile for writing");out.write(kMagic,8);std::vector<std::uint8_t> h;u64(h,payload.size());u64(h,hash(payload));out.write(reinterpret_cast<const char*>(h.data()),16);out.write(reinterpret_cast<const char*>(payload.data()),static_cast<std::streamsize>(payload.size()));if(!out)throw std::runtime_error("failed writing bell modal profile");}

BellModalProfile loadBellModalProfile(const std::string& path,const AcousticFieldCacheIdentity& expected){std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("cannot open bell modal profile");char magic[8];in.read(magic,8);if(!in||std::memcmp(magic,kMagic,8))throw std::runtime_error("invalid bell modal profile magic");std::uint8_t hb[16];in.read(reinterpret_cast<char*>(hb),16);if(!in)throw std::runtime_error("truncated bell modal profile header");std::vector<std::uint8_t> hv(hb,hb+16);Reader hr{hv};auto n=hr.get64(),sum=hr.get64();if(n>kMaxPayload)throw std::runtime_error("bell modal profile too large");std::vector<std::uint8_t> b(static_cast<std::size_t>(n));in.read(reinterpret_cast<char*>(b.data()),static_cast<std::streamsize>(b.size()));if(!in||in.peek()!=std::char_traits<char>::eof()||hash(b)!=sum)throw std::runtime_error("bell modal profile truncated or checksum mismatch");Reader r{b};if(r.get32()!=kVersion)throw std::runtime_error("unsupported bell modal profile version");BellModalProfile p;p.identity={r.getString(),r.getString(),r.getString()};if(p.identity.geometry_fingerprint!=expected.geometry_fingerprint||p.identity.material_fingerprint!=expected.material_fingerprint||p.identity.solver_fingerprint!=expected.solver_fingerprint)throw std::runtime_error("bell modal profile identity mismatch");auto points=[&](std::vector<Point2D>& v){auto count=r.get32();if(count<2||count>1000000)throw std::runtime_error("invalid modal profile geometry count");v.resize(count);for(auto& q:v){q.r=r.getReal();q.z=r.getReal();}};points(p.inner_profile);points(p.outer_profile);auto count=r.get32();if(!count||count>10000)throw std::runtime_error("invalid modal profile mode count");p.modes.resize(count);for(auto& m:p.modes){m.mode_number=static_cast<int>(static_cast<std::int32_t>(r.get32()));m.eigenvalue=r.getReal();m.frequency_hz=r.getReal();m.modal_mass=r.getReal();m.decay_time=r.getReal();m.inner_harmonics=r.getInts();m.inner_radial=r.getDoubles();m.inner_azimuthal=r.getDoubles();m.inner_axial=r.getDoubles();m.outer_harmonics=r.getInts();m.outer_radial=r.getDoubles();m.outer_azimuthal=r.getDoubles();m.outer_axial=r.getDoubles();}if(r.p!=b.size()||!p.valid())throw std::runtime_error("invalid or trailing data in bell modal profile");return p;}

std::vector<ModalMode> reconstructBoundaryModes(const BellModalProfile& p){if(!p.valid())throw std::invalid_argument("cannot reconstruct modes from invalid bell modal profile");std::vector<ModalMode> out;out.reserve(p.modes.size());for(const auto& src:p.modes){ModalMode m;m.mode_number=src.mode_number;m.eigenvalue=src.eigenvalue;m.frequency_hz=src.frequency_hz;m.modal_mass=src.modal_mass;m.decay_time=src.decay_time;m.inner_surface_harmonics=src.inner_harmonics;m.inner_surface_fourier_radial=src.inner_radial;m.inner_surface_fourier_azimuthal=src.inner_azimuthal;m.inner_surface_fourier_axial=src.inner_axial;m.outer_surface_harmonics=src.outer_harmonics;m.outer_surface_fourier_radial=src.outer_radial;m.outer_surface_fourier_azimuthal=src.outer_azimuthal;m.outer_surface_fourier_axial=src.outer_axial;if(src.inner_harmonics.size()==1&&src.inner_harmonics[0]==0){m.inner_surface_radial=src.inner_radial;m.inner_surface_axial=src.inner_axial;}if(src.outer_harmonics.size()==1&&src.outer_harmonics[0]==0){m.outer_surface_radial=src.outer_radial;m.outer_surface_axial=src.outer_axial;}out.push_back(std::move(m));}return out;}

void saveBellModalProfileBundle(const std::string& basePath,const BellModalProfile& p,unsigned polarSamples){
 if(basePath.empty()||!p.valid())throw std::invalid_argument("invalid bell modal profile bundle");
 auto modes=reconstructBoundaryModes(p);std::vector<const ModalMode*> refs;refs.reserve(modes.size());for(const auto& m:modes)refs.push_back(&m);
 auto radiation=buildAcousticFieldCache(refs,p.outer_profile,p.identity,polarSamples);
 saveBellModalProfile(basePath+".bmodal",p);saveAcousticFieldCache(basePath+".acfield",radiation);
}

BellModalProfileBundle loadBellModalProfileBundle(const std::string& basePath,const AcousticFieldCacheIdentity& expected){
 if(basePath.empty())throw std::invalid_argument("empty bell modal profile bundle path");
 BellModalProfileBundle b;b.structural=loadBellModalProfile(basePath+".bmodal",expected);b.radiation=loadAcousticFieldCache(basePath+".acfield",expected);
 if(b.structural.modes.size()!=b.radiation.modes.size())throw std::runtime_error("bell modal profile bundle mode-count mismatch");
 for(std::size_t i=0;i<b.structural.modes.size();++i)if(std::abs(b.structural.modes[i].frequency_hz-b.radiation.modes[i].frequency_hz)>1e-9*std::max(1.0,b.structural.modes[i].frequency_hz))throw std::runtime_error("bell modal profile bundle frequency mismatch");
 return b;
}

} // namespace BellOptimizer::Acoustics
